import type { ElementTable } from "claude-code";

import type { MemFile } from "../types";
import { noLink, shortPath, tokens } from "./format";

/** Lines of a file shown in its preview; the rest is counted, `↗ open` shows it whole. */
export const PREVIEW_LINES = 60;

export type MemoryProps = {
  /** Width of the pane body, for the preview frame. */
  columns: number;
  cwd: string;
  /** CLAUDE.md, CLAUDE.local.md and AGENTS.md files in context. */
  files: readonly MemFile[];
  /** Files whose preview is open. */
  expanded: readonly string[];
  /** File text by path, read when its preview opened; absent while it loads or failed. */
  previews: Readonly<Record<string, string>>;
  onToggle: (path: string) => void;
  /** Opens a file in the system. */
  onOpen: (path: string) => void;
};

/** The CLAUDE.md pane: one row per memory file; a click shows its text in an indented frame. */
export function renderMemory(el: ElementTable, p: MemoryProps) {
  const { Box, Button, Text } = el;

  if (p.files.length === 0) {
    return (
      <Box paddingX={1}>
        <Text dimColor>
          No {noLink("CLAUDE.md")} or {noLink("AGENTS.md")} in context.
        </Text>
      </Box>
    );
  }

  return (
    <Box flexDirection="column" paddingX={1}>
      {p.files.map((f) => {
        const isOpen = p.expanded.includes(f.path);
        const text = p.previews[f.path];
        const lines = text === undefined ? [] : text.split(/\r?\n/);
        const rest = lines.length - PREVIEW_LINES;

        return (
          <Box key={f.path} flexDirection="column">
            <Box columnGap={2}>
              {/* noLink: the terminal would turn a file name into a link that opens the file. */}
              <Button
                key={`m:${f.path}`}
                plain
                onPress={() => p.onToggle(f.path)}
              >
                <Text>
                  {isOpen ? "▾" : "▸"}{" "}
                  <Text bold color="suggestion">
                    {noLink(shortPath(f.path, p.cwd))}
                  </Text>
                  <Text dimColor>
                    {"  "}
                    {f.type} · {tokens(f.tokens)} tok
                  </Text>
                </Text>
              </Button>
              <Button
                key={`o:${f.path}`}
                plain
                onPress={() => p.onOpen(f.path)}
              >
                <Text dimColor underline>
                  ↗ open
                </Text>
              </Button>
            </Box>
            {isOpen ? (
              // The text in its own dim frame, indented under the row, with an empty row after.
              <Box flexDirection="column" paddingLeft={4} paddingBottom={1}>
                <Box
                  flexDirection="column"
                  borderStyle="round"
                  borderColor="subtle"
                  paddingX={1}
                  width={Math.max(20, p.columns - 6)}
                >
                  {text === undefined ? (
                    <Text dimColor>reading…</Text>
                  ) : (
                    <Text>{lines.slice(0, PREVIEW_LINES).join("\n")}</Text>
                  )}
                  {rest > 0 ? (
                    <Text dimColor>
                      … {rest} more lines · ↗ open shows the whole file
                    </Text>
                  ) : null}
                </Box>
              </Box>
            ) : null}
          </Box>
        );
      })}
    </Box>
  );
}

files.hooks/tools.tsx:
import type { ElementTable } from "claude-code";

import type { McpServer, SkillInfo } from "../types";
import {
  green,
  mcpTag,
  serverCalls,
  skillTag,
  sortByUse,
  tokens,
  yellow,
} from "./format";

export type ToolsProps = {
  /** Width of the pane body, for the right-aligned switches and the separator. */
  columns: number;
  mcp: readonly McpServer[];
  /** Calls per tool name (`mcp__server__tool`). */
  calls: Readonly<Record<string, number>>;
  skills: readonly SkillInfo[];
  /** Calls per skill name. */
  skillCalls: Readonly<Record<string, number>>;
  /** MCP servers switched off: listed after the active ones, drawn OFF. */
  disabledMcp: readonly string[];
  /** Skills switched off: listed after the active ones, drawn OFF. */
  disabledSkills: readonly string[];
  onToggleMcp?: (server: string) => void;
  onToggleSkill?: (skill: string) => void;
};

/** One row: name and details on the left, the ON/OFF switch at the right edge. */
type Row = {
  key: string;
  name: string;
  detail: string;
  isOn: boolean;
  /** `system`, `plugin`, `claude.ai`; empty for the person's own. */
  tag: string;
  onToggle?: () => void;
};

/** The MCP & skills pane: MCP servers, a separator, then skills; each list active first, most called first. */
export function renderTools(el: ElementTable, p: ToolsProps) {
  const { Box, Button, Text } = el;
  // The rows sit 1 cell in from each side of the pane body.
  const width = Math.max(20, p.columns - 2);

  const mcpRows: Row[] = sortByUse([
    ...p.mcp.map((s) => ({
      name: s.server,
      calls: serverCalls(p.calls, s.server),
      isOn: !p.disabledMcp.includes(s.server),
      detail: `${s.loaded}/${s.tools} tools · ${tokens(s.tokens)} tok`,
      tag: mcpTag(s.server),
    })),
    // A server switched off is no longer in the context: it is only named.
    ...p.disabledMcp
      .filter((name) => !p.mcp.some((s) => s.server === name))
      .map((name) => ({
        name,
        calls: 0,
        isOn: false,
        detail: "",
        tag: mcpTag(name),
      })),
  ]).map((r) => ({
    key: `mcp:${r.name}`,
    name: r.name,
    detail: `${r.calls} calls${r.detail === "" ? "" : ` · ${r.detail}`}`,
    isOn: r.isOn,
    tag: r.tag,
    onToggle:
      p.onToggleMcp === undefined ? undefined : () => p.onToggleMcp?.(r.name),
  }));

  const skillRows: Row[] = sortByUse([
    ...p.skills.map((s) => ({
      name: s.name,
      calls: p.skillCalls[s.name] ?? 0,
      isOn: !p.disabledSkills.includes(s.name),
      detail: `${s.source} · ${tokens(s.tokens)} tok`,
      tag: skillTag(s.source),
      // skillOverrides does not apply to a plugin's skills: no switch for them.
      isSwitchable: s.source !== "plugin",
    })),
    ...p.disabledSkills
      .filter((name) => !p.skills.some((s) => s.name === name))
      .map((name) => ({
        name,
        calls: 0,
        isOn: false,
        detail: "",
        tag: "",
        isSwitchable: true,
      })),
  ]).map((r) => ({
    key: `skill:${r.name}`,
    name: r.name,
    detail: `${r.calls} calls${r.detail === "" ? "" : ` · ${r.detail}`}`,
    isOn: r.isOn,
    tag: r.tag,
    onToggle:
      p.onToggleSkill === undefined || !r.isSwitchable
        ? undefined
        : () => p.onToggleSkill?.(r.name),
  }));

  const row = (r: Row) => (
    <Box key={r.key} justifyContent="space-between" width={width}>
      <Text>
        <Text bold={r.isOn} dimColor={!r.isOn}>
          {r.name}
        </Text>
        {r.tag === "" ? null : (
          <Text
            color={r.tag === "system" ? yellow : undefined}
            dimColor={r.tag !== "system"}
          >
            {" "}
            [{r.tag}]
          </Text>
        )}
        <Text dimColor> {r.detail}</Text>
      </Text>
      {r.onToggle === undefined ? (
        <Text dimColor={!r.isOn} color={r.isOn ? green : undefined}>
          {r.isOn ? " ON" : "OFF"}
        </Text>
      ) : (
        <Button key={`t:${r.key}`} plain onPress={r.onToggle}>
          <Text dimColor={!r.isOn} color={r.isOn ? green : undefined}>
            {r.isOn ? " ON" : "OFF"}
          </Text>
        </Button>
      )}
    </Box>
  );

  return (
    <Box flexDirection="column" paddingX={1}>
      {/* Every switch changes what the model is told it has, so the prompt prefix changes. */}
      <Text color={yellow}>
        ⚠ Any switch changes the tools and skills listed to the model: the next
        request writes the prompt cache again.
      </Text>
      <Text> </Text>
      <Text dimColor>MCP servers</Text>
      {mcpRows.length === 0 ? (
        <Text dimColor>No MCP server.</Text>
      ) : (
        mcpRows.map(row)
      )}
      <Text dimColor>{"─".repeat(width)}</Text>
      <Text dimColor>Skills</Text>
      {skillRows.length === 0 ? (
        <Text dimColor>No skill.</Text>
      ) : (
        skillRows.map(row)
      )}
    </Box>
  );
}

files.hooks/robot.tsx:
import type { ElementTable } from "claude-code";

import { spinner } from "./format";

/** Mini Clawd from the Claude Code welcome screen: head and body, two rows of 5 cells. */
const IDLE = ["▐▛█▜▌", "▝▜█▛▘"];
const BLINK = ["▐███▌", "▝▜█▛▘"];
/** While working it waves its arms and darts its eyes; the fourth frame blinks. */
const WORKING = [
  ["▐▛█▜▌", "▝▜█▛▘"],
  ["▐▛█▜▌", "▗▟█▙▖"],
  ["▐▜█▛▌", "▝▜█▛▘"],
  ["▐███▌", "▗▟█▙▖"],
];

export type RobotProps = {
  isWorking: boolean;
  /** Frame counter; while working it grows four times per second. */
  frame: number;
  /** Current time in milliseconds; when idle the robot blinks once every few seconds. */
  now: number;
};

/** Animated mini robot next to the limits: works while a turn is running, otherwise stands still and blinks now and then. */
export function renderRobot(el: ElementTable, p: RobotProps) {
  const { Box, Text } = el;
  const isBlink = Math.floor(p.now / 1000) % 6 === 0;
  const rows = p.isWorking
    ? (WORKING[p.frame % WORKING.length] ?? IDLE)
    : isBlink
      ? BLINK
      : IDLE;
  const spin = p.isWorking ? spinner(p.frame) : " ";
  // In color only while working; at rest it stays in the background.
  const color = p.isWorking ? "claude" : undefined;

  return (
    <Box flexDirection="column">
      <Text color={color} dimColor={!p.isWorking}>
        {rows[0]}
      </Text>
      <Text color={color} dimColor={!p.isWorking}>
        {rows[1]} {spin}
      </Text>
    </Box>
  );
}

